Example: Find minimum of a set of numbers
•/*C program to demonstrate the use of variable number of arguments*/ 
•#include < stdio.h > 
•/* this function returns minimum of integer numbers passed*/
•/*First argument is count of optional arguments*/
•int min(int arg_count , ...) 
•{ 
•int i; 
•int minm , a;  
•/* va_list is a type to hold information about variable arguments*/ 
•va_list ap; 
•/* va_start must be called before accessing variable argument list */
•va_start (ap, arg_count );   
•/* arguments can be accessed one by one using va_arg macro*/ 
13
Example: Find minimum of a set of numbers contd..
•/*Initialize min as first argument in the list */
•minm = va_arg (ap, int);
•printf ("initial minm is %d \n",minm );
•/* Check rest of the arguments to find out minimum*/ 
•for (i= 2; i<= arg_count ; i++) {
• a = va_arg (ap, int);
• printf ("Next integer moved to is %d \n",a);
• if ((a < minm ))
• minm = a; }  
•/* va_end should be executed before the function returns whenever va_start has been 
used*/ 
•va_end (ap);   
•return minm ; 
•} 
